mapper.select:
SELECT
    t2.`name`    AS customer_name,
    t4.nickname  AS creator_name,
    t1.id, t1.order_no, t1.customer_id, t1.mobile, t1.brand_id,
    t1.order_date, t1.logistic_id, t1.logistic_name, t1.receiver, t1.delivery_address,
    t1.freight, t1.types, t1.discount_amount, t1.total_amount,
    t1.amount, t1.rounding, t1.amount_received, t1.delivery_date, t1.pay_status,
    t1.status, t1.confirm_time, t1.is_expedited, t1.sets, t1.note,
    t1.current_node_name, t1.create_time, t1.update_time, t1.creator, t1.updater
FROM zc_sales_order t1
LEFT JOIN zc_customer   t2 ON t1.customer_id = t2.id  AND t2.deleted = 0
LEFT JOIN system_users  t4 ON t1.creator      = t4.id AND t4.deleted = 0
WHERE t1.deleted = 0

    AND t1.order_no LIKE CONCAT('%', #{reqVO.orderNo}, '%')


    AND t1.customer_id = #{reqVO.customerId}


    AND t1.brand_id = #{reqVO.brandId}


    AND t1.order_date BETWEEN #{reqVO.orderDate[0]} AND #{reqVO.orderDate[1]}


    AND t1.logistic_id = #{reqVO.logisticId}


    AND t1.types = #{reqVO.types}


    AND t1.delivery_date BETWEEN #{reqVO.deliveryDate[0]} AND #{reqVO.deliveryDate[1]}


    AND t1.pay_status IN

        #{ps}



    AND t1.status IN

        #{s}





            AND t1.confirm_time IS NOT NULL


            AND t1.confirm_time IS NULL




    AND t1.is_expedited = #{reqVO.isExpedited}

ORDER BY t1.id DESC
